"""Embed the reviewable, nonsecret session helper in the installed CLI worker."""
import base64
from pathlib import Path
root = Path(__file__).resolve().parents[1]
source = (root / 'scripts/ssh_session/remote_helper.py').read_bytes()
encoded = base64.b64encode(source).decode()
lines = [encoded[i:i+100] for i in range(0, len(encoded), 100)]
(root / 'packages/info_cli/lib/ssh_session_remote_source.dart').write_text(
    '// Generated by scripts/generate-ssh-session-source.py; do not edit.\n'
    'const sshSessionRemoteSourceBase64 =\n' + '\n'.join("    '" + line + "'" for line in lines) + ';\n')
